waves.point_eqs_str:
u = abs(cos(q1*0.1))*3.14159;
v = abs(cos(q1*0.015))*3.14159*2;
s = sample*3.14*100;
ss = sample*6.28*1000;

//draw
xs = (0.5 + 0.01*cos(s))*cos(ss);
ys = (0.5 + 0.01*cos(s))*sin(ss);
zs = 0.5*sin(s);

//rotate x axis
angle = q1*0.1;
yx = ys*cos(angle) - zs*sin(angle);
zx = ys*sin(angle) + zs*cos(angle);
xx = xs;

//rotate y axis
angle2 = q1*0.14;
xd = xx*cos(angle2) - zx*sin(angle2);
zd = xx*sin(angle2) + zx*cos(angle2);
yd = yx;

//rotaye z axis
angle3 = q1*0.15;
xn = xd*cos(angle3) - yd*sin(angle3);
yn = xd*sin(angle3) + yd*cos(angle3);

zd = zd + 2;

x = xn*zd*0.3 + 0.5;
y = yn*zd*0.3*1.2 + 0.5;

r = 0.5 + 0.5*sin(q1*1.2 + x + x);
g = 0.5 + 0.5*sin(q1*1.5 + x + y);
b = 0.5 + 0.5*sin(q1*1.66 + y + y);

